from payments import gateway, service


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    An optional Idempotency-Key header (any case) makes retries safe: the same
    key and body get the first response again, and nothing is charged twice.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    idempotency_key = _header(request, "Idempotency-Key")
    if idempotency_key is not None and (type(idempotency_key) is not str or not idempotency_key):
        return 400, {"error": "Idempotency-Key must be a non-empty string"}
    try:
        payment = service.create_payment(conn, customer_id, cents, idempotency_key)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except service.IdempotencyKeyReused:
        return 409, {"error": "idempotency key reused"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    return 201, payment


def _header(request, name):
    """Return the header's value, matching its name without regard to case."""
    for key, value in (request.get("headers") or {}).items():
        if key.lower() == name.lower():
            return value
    return None

