import sqlite3

from payments import gateway


class UnknownCustomer(Exception):
    pass


class IdempotencyKeyReused(Exception):
    """The key belongs to an earlier payment with a different customer or amount."""


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key with the
    same customer and amount is returned again without a new charge; one with a
    different customer or amount raises IdempotencyKeyReused.
    """
    if idempotency_key is None:
        if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
            raise UnknownCustomer(customer_id)
        charge_id = gateway.charge(conn, cents)
        cur = conn.execute("INSERT INTO payments (customer_id, cents, charge_id) VALUES (?, ?, ?)",
                           (customer_id, cents, charge_id))
        conn.commit()
        return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

    # Take the database write lock before the lookup, so the lookup, the charge
    # and the insert run as one unit: another worker sending the same key waits
    # here, then finds the committed payment and replays it instead of charging.
    conn.execute("BEGIN IMMEDIATE")
    try:
        if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
            raise UnknownCustomer(customer_id)
        existing = _find_by_key(conn, idempotency_key)
        if existing is not None:
            conn.commit()
            return _replay(existing, customer_id, cents)
        charge_id = gateway.charge(conn, cents)
        try:
            cur = conn.execute(
                "INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
                (customer_id, cents, charge_id, idempotency_key))
        except sqlite3.IntegrityError:
            # Another writer stored the key first. The write lock should make this
            # impossible; if it happens anyway, answer from the stored payment.
            # Rolling back does not undo charge_id at a real processor.
            conn.rollback()
            existing = _find_by_key(conn, idempotency_key)
            if existing is None:
                raise
            return _replay(existing, customer_id, cents)
        conn.commit()
    except BaseException:
        if conn.in_transaction:
            conn.rollback()
        raise
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}


def _find_by_key(conn, idempotency_key):
    return conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                        (idempotency_key,)).fetchone()


def _replay(row, customer_id, cents):
    if (row["customer_id"], row["cents"]) != (customer_id, cents):
        raise IdempotencyKeyReused()
    return {"id": row["id"], "customer_id": row["customer_id"], "cents": row["cents"],
            "charge_id": row["charge_id"]}

