"""MANIFEST.json, written at the root of every backup: the sha256 of each file and the target of each link."""
import hashlib
import json
import os

from archive import paths
from archive.errors import UnsafeArchive
from archive.pack import walk

NAME = "MANIFEST.json"


class ManifestMismatch(ValueError):
    pass


def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 16), b""):
            digest.update(block)
    return digest.hexdigest()


def build(root):
    """{"files": {path: sha256}, "links": {path: target}} for the tree under root, paths relative and POSIX."""
    files, links = {}, {}
    for rel, path in walk(root):
        if rel == NAME:
            continue
        if os.path.islink(path):
            links[rel] = os.readlink(path)
        elif os.path.isfile(path):
            files[rel] = sha256(path)
    return {"files": files, "links": links}


def dumps(manifest):
    return json.dumps(manifest, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def verify(root, manifest):
    """ManifestMismatch unless every file and link the manifest lists is under root as it says. The manifest is
    written by whoever uploaded the backup, so each name must be a path inside the backup before anything is read:
    a name that climbs out of root is refused, never read."""
    if not isinstance(manifest, dict):
        raise ManifestMismatch(f"the backup's {NAME} must hold an object")
    for rel, digest in _listed(manifest, "files").items():
        path = _inside(root, rel)
        if os.path.islink(path) or not os.path.isfile(path):
            raise ManifestMismatch(f"{rel} is missing")
        if sha256(path) != digest:
            raise ManifestMismatch(f"{rel} doesn't match its checksum")
    for rel, target in _listed(manifest, "links").items():
        path = _inside(root, rel)
        if not os.path.islink(path) or os.readlink(path) != target:
            raise ManifestMismatch(f"{rel} should link to {target}")


def _listed(manifest, key):
    value = manifest.get(key, {})
    if not isinstance(value, dict):
        raise ManifestMismatch(f"the backup's {NAME} has a bad {key} list")
    return value


def _inside(root, rel):
    try:
        name = paths.clean_name(rel)
    except UnsafeArchive:
        raise ManifestMismatch(f"{rel!r} isn't a path inside the backup") from None
    return os.path.join(root, *name.split("/"))

