"""A model of the destination folder as the extraction will leave it, so every member is checked against the paths
it will really take: the real ones, with each link in the archive followed, not the ones its name spells.

Paths here are tuples of names relative to the destination, and a "canonical" path is one with no link in it.
"""
import os
import stat

from .errors import UnsafeArchive

MAX_LINK_HOPS = 40  # the kernel's own limit is of this order


def split(path):
    return [part for part in path.split("/") if part not in ("", ".")]


class Tree:
    def __init__(self, root):
        self.root = root  # the real, absolute path of the destination
        self.nodes = {}   # canonical path -> ("dir",) | ("file",) | ("link", target), for what the archive adds

    def lookup(self, parts):
        """What is at the canonical path `parts`, links not followed: what the archive adds, else what is on disk."""
        node = self.nodes.get(parts)
        if node is not None:
            return node
        path = os.path.join(self.root, *parts)
        try:
            mode = os.lstat(path).st_mode
        except (FileNotFoundError, NotADirectoryError):
            return None
        if stat.S_ISDIR(mode):
            return ("dir",)
        if stat.S_ISLNK(mode):
            return ("link", os.readlink(path))
        return ("file",)

    def walk(self, base, path, created=None):
        """The canonical path that `path` leads to from the canonical directory `base`, following every link on
        the way, the last component included. Components that don't exist yet are kept as they are, and when
        created is a list they are added to the model as folders and to that list. UnsafeArchive if the walk
        leaves the destination or meets an absolute link. A walk that is for a place to write into (created is a
        list) is also refused when it meets a file or loops; otherwise a loop gives None, a file is just passed."""
        cur = list(base)
        todo = split(path)[::-1]
        hops = 0
        while todo:
            part = todo.pop()
            if part == "..":
                if not cur:
                    raise UnsafeArchive(f"{path} leads out of the destination")
                cur.pop()
                continue
            cur.append(part)
            node = self.lookup(tuple(cur))
            if node is None:
                if created is not None:
                    self.nodes[tuple(cur)] = ("dir",)
                    created.append(tuple(cur))
            elif node[0] == "link":
                hops += 1
                if hops > MAX_LINK_HOPS:
                    if created is None:
                        return None  # a loop leads nowhere, so there is nothing to check
                    raise UnsafeArchive(f"{path} goes through too many links")
                if not node[1] or node[1].startswith("/"):
                    raise UnsafeArchive(f"{'/'.join(cur)} links to an absolute path")
                cur.pop()
                todo.extend(split(node[1])[::-1])
            elif node[0] == "file" and created is not None:
                raise UnsafeArchive(f"{'/'.join(cur)} is not a folder but {path} goes through it")
        return tuple(cur)

