import sqlite3

from payments import gateway, service


def handle_post(conn, request):
    """POST /payments. The body is {"customer_id": int, "cents": int}.

    An Idempotency-Key header lets a client retry safely; see _charge_once.
    """
    body = request.get("body") or {}
    customer_id, cents = body.get("customer_id"), body.get("cents")
    if type(customer_id) is not int or type(cents) is not int or cents <= 0:
        return 400, {"error": "customer_id and a positive cents are required"}
    key = _idempotency_key(request.get("headers") or {})
    if key is not None:
        if not key:
            return 400, {"error": "Idempotency-Key must not be empty"}
        return _charge_once(conn, key, customer_id, cents)
    try:
        payment = service.create_payment(conn, customer_id, cents)
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        conn.rollback()
        return 402, {"error": f"declined: {e}"}
    return 201, payment


def _idempotency_key(headers):
    """The stripped Idempotency-Key value, or None if the header is absent. Header names are case-insensitive."""
    for name, value in headers.items():
        if name.lower() == "idempotency-key":
            return str(value).strip()
    return None


def _payment_for_key(conn, key):
    return conn.execute("SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
                        (key,)).fetchone()


def _charge_once(conn, key, customer_id, cents):
    """Charge at most once per key.

    BEGIN IMMEDIATE takes the write lock before the lookup, so a second request with the same key
    waits here and then finds the first one's row. Every path ends the transaction: a commit inside
    service.create_payment on success, otherwise the rollback in finally.
    """
    if conn.in_transaction:
        conn.commit()  # sqlite3 may have left a transaction open; BEGIN would fail inside it
    conn.execute("BEGIN IMMEDIATE")
    try:
        row = _payment_for_key(conn, key)
        if row is None:
            try:
                return 201, service.create_payment(conn, customer_id, cents, idempotency_key=key)
            except sqlite3.IntegrityError:
                # Backstop for a unique-index hit the lock should have prevented. Undo this attempt, then replay.
                conn.rollback()
                row = _payment_for_key(conn, key)
                if row is None:
                    raise
        payment_id, stored_customer_id, stored_cents, charge_id = row
        if (stored_customer_id, stored_cents) != (customer_id, cents):
            return 409, {"error": "idempotency key reused"}
        return 201, {"id": payment_id, "customer_id": stored_customer_id, "cents": stored_cents,
                     "charge_id": charge_id}
    except service.UnknownCustomer:
        return 404, {"error": "no such customer"}
    except gateway.Declined as e:
        return 402, {"error": f"declined: {e}"}
    finally:
        if conn.in_transaction:
            conn.rollback()

