from payments import gateway


class UnknownCustomer(Exception):
    pass


class IdempotencyConflict(Exception):
    """The key was already used for a payment with a different customer or amount."""


def create_payment(conn, customer_id, cents, idempotency_key=None):
    """Charge the customer and record the payment; return it as a dict.

    With an idempotency_key, a payment already stored under that key is returned
    without a new charge, and IdempotencyConflict is raised if its customer or
    amount differs. The key lookup and the charge run in one BEGIN IMMEDIATE
    transaction, so two requests with the same key cannot both charge. Declines and
    other errors are rolled back, so nothing is stored and a retry tries again.
    """
    if idempotency_key is None:
        return _charge_and_record(conn, customer_id, cents, None)
    # The connection must not already have a transaction open (BEGIN would fail).
    # Python's sqlite3 does not issue its own BEGIN before an explicit one.
    conn.execute("BEGIN IMMEDIATE")
    try:
        row = conn.execute(
            "SELECT id, customer_id, cents, charge_id FROM payments WHERE idempotency_key = ?",
            (idempotency_key,)).fetchone()
        if row is not None:
            if (row[1], row[2]) != (customer_id, cents):
                raise IdempotencyConflict(idempotency_key)
            conn.commit()  # nothing was written; this just ends the transaction and releases the lock
            return {"id": row[0], "customer_id": row[1], "cents": row[2], "charge_id": row[3]}
        return _charge_and_record(conn, customer_id, cents, idempotency_key)
    except BaseException:
        conn.rollback()
        raise


def _charge_and_record(conn, customer_id, cents, idempotency_key):
    if conn.execute("SELECT 1 FROM customers WHERE id = ?", (customer_id,)).fetchone() is None:
        raise UnknownCustomer(customer_id)
    charge_id = gateway.charge(conn, cents)
    cur = conn.execute(
        "INSERT INTO payments (customer_id, cents, charge_id, idempotency_key) VALUES (?, ?, ?, ?)",
        (customer_id, cents, charge_id, idempotency_key))
    conn.commit()
    return {"id": cur.lastrowid, "customer_id": customer_id, "cents": cents, "charge_id": charge_id}

