import contextlib


class InsufficientFunds(Exception):
    pass


def balance(store, wallet):
    """The wallet's balance in cents, 0 for a wallet the store hasn't seen."""
    return store.get(wallet) or 0


def _check_cents(cents):
    if not isinstance(cents, int) or isinstance(cents, bool) or cents < 0:
        raise ValueError(f"cents must be a non-negative whole number, got {cents!r}")


@contextlib.contextmanager
def _held(store, *wallets):
    """Hold the lock of each distinct wallet, always taken in sorted order, so two transfers
    touching the same pair in opposite directions cannot each hold one lock and wait for the
    other. Every lock taken is released on exit, including when the body raises."""
    with contextlib.ExitStack() as stack:
        for name in sorted(set(wallets)):
            stack.enter_context(store.lock(name))
        yield


def credit(store, wallet, cents):
    """Add cents to the wallet."""
    _check_cents(cents)
    with _held(store, wallet):
        store.put(wallet, balance(store, wallet) + cents)


def transfer(store, src, dst, cents):
    """Move cents from src to dst; raise InsufficientFunds when src holds less.

    A transfer to the same wallet checks the funds and then changes nothing."""
    _check_cents(cents)
    with _held(store, src, dst):
        available = balance(store, src)
        if available < cents:
            raise InsufficientFunds(src)
        if src == dst:
            return
        store.put(src, available - cents)
        store.put(dst, balance(store, dst) + cents)

files.archive/extract.py:
"""Unpacking a tar archive into a folder without letting it reach outside that folder.

Archives reach us from two places, plugin bundles (plugins/installer.py) and user backups (backups/restore.py), and
neither is trusted. safe_extract checks every member before it writes anything, so an archive it refuses leaves
the destination as it was.

Checking a member's name on its own isn't enough: a link earlier in the archive can make a later, innocent-looking
name ("a/b/file") land somewhere else, and a link's target ("../x") means something different once one of the
folders on its way is itself a link. So the plan is made against a model of the tree as the archive builds it:
every member's folder is resolved through the links already in that tree, the member is written to the resolved
place, and every link is checked against the finished tree. The writes then open each folder on the way without
following links, so nothing that differs from the plan (a link already in dest, a race) can lead them out.
"""
import errno
import os
import shutil
import stat
import tarfile

from . import limits, paths
from .errors import UnsafeArchive

FILE_MODE = 0o644
EXEC_MODE = 0o755
MAX_LINK_HOPS = 40  # what Linux follows before ELOOP

DIR, FILE, LINK = "dir", "file", "link"
_NOFOLLOW = getattr(os, "O_NOFOLLOW", 0)
_DIRECTORY = getattr(os, "O_DIRECTORY", 0)
_CLOEXEC = getattr(os, "O_CLOEXEC", 0)


def safe_extract(tar_path, dest):
    """Extract the tar at tar_path into the existing folder dest; return the member names, in archive order.

    Regular files, folders and symbolic links are extracted, and a link may point only inside dest. A member that
    would land outside dest, a link that points outside it, a name listed twice, any other kind of member or an
    archive over the size limits raises UnsafeArchive, and then nothing has been written."""
    root = os.path.realpath(dest)
    if not os.path.isdir(root):
        raise NotADirectoryError(dest)
    with tarfile.open(tar_path) as tar:
        members = tar.getmembers()
        limits.check(members)
        plan = plan_members(root, members)
        for member, parts in plan:
            write_member(root, tar, member, parts)
    return [paths.clean_name(m.name) for m in members]


class _Tree:
    """What dest will hold, as the archive builds it: {(part, ...): (kind, linkname)}. A path the archive hasn't
    made yet is looked up in dest itself, so links already there count too."""

    def __init__(self, root):
        self.root = root
        self.nodes = {(): (DIR, None)}

    def get(self, parts):
        if parts not in self.nodes:
            path = os.path.join(self.root, *parts)
            try:
                st = os.lstat(path)
            except FileNotFoundError:
                return None
            except OSError as e:
                raise UnsafeArchive(f"can't check {'/'.join(parts)} in the destination: {e}") from None
            if stat.S_ISLNK(st.st_mode):
                self.nodes[parts] = (LINK, os.readlink(path))
            elif stat.S_ISDIR(st.st_mode):
                self.nodes[parts] = (DIR, None)
            else:
                self.nodes[parts] = (FILE, None)
        return self.nodes[parts]

    def resolve(self, start, rel_parts, what, make_folders):
        """The path, as parts under root, that rel_parts reach from the folder start, following every link on the
        way (the last part too) the way the kernel would. UnsafeArchive if the way leaves root at any point, loops
        or goes through a file.

        With make_folders, the whole path is a folder the member goes in: missing parts are recorded as folders
        to be made and a file anywhere is refused. Without it, the rest of a path past a missing part is taken
        as written, but never with a ".." after the missing part (the kernel would stop there, and the name might
        yet match something else on a case-insensitive filesystem)."""
        hops = [0]
        return self._walk(list(start), list(rel_parts), what, make_folders, hops, False)

    def _walk(self, cur, todo, what, make_folders, hops, more_after):
        missing = False
        todo = [p for p in todo if p not in ("", ".")]
        while todo:
            part = todo.pop(0)
            if part == "..":
                if missing:
                    raise UnsafeArchive(f"{what} goes up out of a folder that isn't in the archive")
                if not cur:
                    raise UnsafeArchive(f"{what} leads outside the destination")
                cur.pop()
                continue
            nxt = cur + [part]
            if missing:
                cur = nxt
                continue
            node = self.get(tuple(nxt))
            if node is None:
                if make_folders:
                    self.nodes[tuple(nxt)] = (DIR, None)
                else:
                    missing = True
                cur = nxt
                continue
            kind, linkname = node
            if kind == LINK:
                hops[0] += 1
                if hops[0] > MAX_LINK_HOPS:
                    raise UnsafeArchive(f"{what} goes through too many links (a loop?)")
                check_linkname(what, linkname)
                cur = self._walk(cur, linkname.split("/"), what, make_folders, hops, more_after or bool(todo))
                continue
            if kind == FILE and (make_folders or todo or more_after):
                raise UnsafeArchive(f"{what} goes through the file {'/'.join(nxt)}")
            cur = nxt
        return cur


def check_linkname(what, linkname):
    if (not linkname or "\x00" in linkname or "\\" in linkname or os.path.isabs(linkname)
            or linkname.startswith("/") or (len(linkname) > 1 and linkname[1] == ":")):
        raise UnsafeArchive(f"{what} links to an absolute or malformed path {linkname!r}")


def plan_members(root, members):
    """[(member, the parts under root it goes to), ...] once every member has passed, or UnsafeArchive."""
    seen = set()
    plan = []
    tree = _Tree(root)
    links = []
    for member in members:
        name = paths.clean_name(member.name)
        if name in seen:
            raise UnsafeArchive(f"{name} is listed twice")
        seen.add(name)
        if member.islnk():
            raise UnsafeArchive(f"{name} is a hard link")
        if not (member.isfile() or member.isdir() or member.issym()):
            raise UnsafeArchive(f"{name} is a device, a FIFO or another special file")
        if member.issym():
            check_linkname(name, member.linkname)
        parts = name.split("/")
        # The folder the member goes in, through any links the archive (or dest) has by now.
        folder = tree.resolve((), parts[:-1], name, make_folders=True)
        target = tuple(folder + [parts[-1]])
        existing = tree.get(target)
        if member.isdir():
            if existing is not None and existing[0] != DIR:
                raise UnsafeArchive(f"{name} would replace a link or a file with a folder")
            tree.nodes[target] = (DIR, None)
        else:
            if existing is not None:
                raise UnsafeArchive(f"{name} would replace something already there")
            if member.issym():
                tree.nodes[target] = (LINK, member.linkname)
                links.append((name, target, member.linkname))
            else:
                tree.nodes[target] = (FILE, None)
        plan.append((member, target))
    # Every link, against the finished tree: it, and every link it goes through, must stay inside root.
    for name, target, linkname in links:
        tree.resolve(target[:-1], linkname.split("/"), f"{name} -> {linkname}", make_folders=False)
    return plan


def _open_dir(dir_fd, name, make):
    flags = os.O_RDONLY | _DIRECTORY | _NOFOLLOW | _CLOEXEC
    try:
        return os.open(name, flags, dir_fd=dir_fd)
    except FileNotFoundError:
        if not make:
            raise
    try:
        os.mkdir(name, 0o777, dir_fd=dir_fd)
    except FileExistsError:
        pass
    return os.open(name, flags, dir_fd=dir_fd)


def write_member(root, tar, member, parts):
    """Write member at root/parts, opening each folder on the way without following links."""
    fd = os.open(root, os.O_RDONLY | _DIRECTORY | _CLOEXEC)
    try:
        for part in parts[:-1]:
            nxt = _open_dir(fd, part, make=True)
            os.close(fd)
            fd = nxt
        last = parts[-1]
        if member.isdir():
            os.close(_open_dir(fd, last, make=True))
        elif member.issym():
            os.symlink(member.linkname, last, dir_fd=fd)
        else:
            mode = EXEC_MODE if member.mode & 0o100 else FILE_MODE
            out_fd = os.open(last, os.O_WRONLY | os.O_CREAT | os.O_EXCL | _NOFOLLOW | _CLOEXEC, FILE_MODE,
                             dir_fd=fd)
            with tar.extractfile(member) as src, os.fdopen(out_fd, "wb") as out:
                shutil.copyfileobj(src, out)
                os.fchmod(out.fileno(), mode)
    except OSError as e:
        if e.errno in (errno.ELOOP, errno.ENOTDIR, errno.EEXIST):
            raise OSError(e.errno, f"{'/'.join(parts)} changed under the extraction: {e.strerror}") from None
        raise
    finally:
        os.close(fd)

