from billing import rules


def balances(conn) -> dict[int, int]:
    """Each account's balance in cents, {account_id: cents}: what its invoices that aren't voided ask for, minus the payments on them that rules.counts accepts. Every account is in the result, 0 when it has nothing to pay."""
    # Three statements in total, however many rows there are. The ORDER BY clauses
    # reproduce the order the per-account queries used to return rows in (rowid
    # order within each account / invoice), so the sums are added in the same order.
    account_ids = [account_id for (account_id,) in
                   conn.execute("SELECT id FROM accounts ORDER BY id").fetchall()]
    invoices_by_account = {account_id: [] for account_id in account_ids}
    for invoice_id, account_id, cents in conn.execute(
            "SELECT id, account_id, amount_cents FROM invoices WHERE voided = 0 ORDER BY account_id, id").fetchall():
        invoices = invoices_by_account.get(account_id)
        if invoices is not None:  # invoices of unknown accounts are not reported
            invoices.append((invoice_id, cents))
    payments_by_invoice = {}
    for invoice_id, paid, status, method in conn.execute(
            "SELECT p.invoice_id, p.amount_cents, p.status, p.method FROM payments AS p "
            "JOIN invoices AS i ON i.id = p.invoice_id WHERE i.voided = 0 ORDER BY p.invoice_id, p.id").fetchall():
        payments_by_invoice.setdefault(invoice_id, []).append((paid, status, method))
    result = {}
    for account_id in account_ids:
        owed = 0
        for invoice_id, cents in invoices_by_account[account_id]:
            owed += cents
            for paid, status, method in payments_by_invoice.get(invoice_id, ()):
                if rules.counts(status, method):
                    owed -= paid
        result[account_id] = owed
    return result

