"""Migrate a v2 export to the v3 format.

migrate(src, accounts, dst) reads the v2 export at src (docs/FORMAT_V2.md) and the accounts file at accounts
(data/accounts.json shows the shape), writes the v3 file at dst (docs/FORMAT_V3.md, "Migrating from v2") and
returns the number of records written.

The export is too big to hold in memory, so it is sorted externally: runs of at most CHUNK items are sorted and
spilled to disk, then merged FAN_IN runs at a time. The first sort puts every line in (id, rev, line number)
order, which picks each entry's current revision as the last line of its id. The second sort puts the migrated
records in v3 order. Output goes to a side file that replaces dst only once every line has migrated, so a
MigrationError leaves dst as it was.
"""
import heapq
import itertools
import json
import os
import tempfile

from . import accounts as accounts_file
from . import kinds, money, timefmt, v2, v3
from .errors import FormatError, MigrationError

CHUNK = 100_000  # items held in memory at once while sorting
FAN_IN = 64      # sorted runs merged at once, which bounds the number of open files


def migrate(src, accounts, dst):
    held = accounts_file.load(accounts)
    part = os.fspath(dst) + ".migrating"
    try:
        with open(part, "w", encoding="utf-8", newline="\n") as out, tempfile.TemporaryDirectory() as work:
            count = _write(src, held, out, work)
        os.replace(part, dst)
    finally:
        if os.path.exists(part):
            os.remove(part)
    return count


def _write(src, held, out, work):
    current = _current_revisions(_external_sort(_v2_items(src), lambda item: item[:3], work), held)
    count = 0
    for record in _external_sort(current, v3.order_key, work):
        out.write(v3.dump_line(record))
        count += 1
    return count


def _v2_items(path):
    """[id, rev, line number, record] for every non-blank line of the export, in file order."""
    with open(path, encoding="utf-8") as f:
        for number, text in enumerate(f, 1):
            if not text.strip():
                continue
            try:
                record = json.loads(text)
            except ValueError as e:
                raise FormatError(f"not JSON ({e})", number) from None
            v2.check(record, number)
            yield [record["id"], record["rev"], number, record]


def _current_revisions(items, held):
    """The v3 record for the current revision of each id. Items arrive sorted by id, then rev, then line number,
    so the last item of each id is the current one: the highest rev, and among equal revs the later line."""
    for _, group in itertools.groupby(items, key=lambda item: item[0]):
        for last in group:
            pass
        yield _to_v3(last[3], last[2], held)


def _to_v3(record, number, held):
    """The v3 record for one v2 line. MigrationError, naming the line, when it can't be migrated."""
    kind = kinds.LEGACY.get(record["kind"], record["kind"])
    if kind not in kinds.TYPES:
        raise MigrationError(f"unknown kind {record['kind']!r}", number)
    account = held.get(record["account"])
    if account is None:
        raise MigrationError(f"account {record['account']!r} isn't in the accounts file", number)
    currency = account.currency if record["currency"] is None else record["currency"]
    if not money.is_currency(currency):
        raise MigrationError(f"bad currency {currency!r}", number)
    try:
        minor = money.to_minor(record["amount"], currency)
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    if minor <= 0:
        raise MigrationError(f"amount {record['amount']} isn't positive", number)
    try:
        stamp = timefmt.parse_ts(record["ts"])
        if stamp.tzinfo is None:
            # Naive times are the account's local time (docs/FORMAT_V2.md, History).
            stamp = stamp.replace(tzinfo=account.tz)
        posted_at = timefmt.to_utc_z(stamp)
    except ValueError as e:
        raise MigrationError(str(e), number) from None
    return {"id": record["id"], "account": record["account"], "type": kind,
            "amount_minor": kinds.SIGN[kind] * minor, "currency": currency, "posted_at": posted_at,
            "memo": record["memo"], "source_rev": record["rev"]}


def _external_sort(items, key, work):
    """The items in key order. At most CHUNK of them are held in memory; sorted runs wait in files under work."""
    directory = tempfile.mkdtemp(dir=work)
    runs = []
    chunk = []
    for item in items:
        chunk.append(item)
        if len(chunk) == CHUNK:
            runs.append(_spill(directory, sorted(chunk, key=key)))
            chunk = []
    if chunk:
        runs.append(_spill(directory, sorted(chunk, key=key)))
    while len(runs) > FAN_IN:
        merged = []
        for start in range(0, len(runs), FAN_IN):
            group = runs[start:start + FAN_IN]
            merged.append(_spill(directory, heapq.merge(*map(_read_run, group), key=key)))
            for path in group:
                os.remove(path)
        runs = merged
    yield from heapq.merge(*map(_read_run, runs), key=key)


def _spill(directory, sorted_items):
    """Write items, already in order, to a new file under directory; return its path."""
    fd, path = tempfile.mkstemp(dir=directory)
    with os.fdopen(fd, "w", encoding="utf-8") as f:
        for item in sorted_items:
            f.write(json.dumps(item) + "\n")
    return path


def _read_run(path):
    with open(path, encoding="utf-8") as f:
        for line in f:
            yield json.loads(line)
